export function catalogEntry(id: string | null | undefined): CatalogEntry | undefined {
  return id === null || id === undefined ? undefined : catalog.find((entry) => entry.id === id);
}

export function clientEnvPrefix(id: string): string {
  return `MCP_${id.toUpperCase().replaceAll("-", "_")}`;
}

export function searchCatalog(query: string, limit: number): CatalogEntry[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  const score = (entry: CatalogEntry) => {
    const name = entry.name.toLowerCase();
    const haystack = `${name} ${entry.id} ${entry.category} ${entry.description.toLowerCase()}`;
    return words.reduce((total, word) => total + (name === word ? 10 : name.includes(word) ? 5 : haystack.includes(word) ? 1 : 0), 0);
  };
  return catalog.map((entry) => ({ entry, score: score(entry) })).filter((hit) => words.length === 0 || hit.score > 0).sort((a, b) => b.score - a.score).slice(0, limit).map((hit) => hit.entry);
}
